import{_ as t,o,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"3.4.21 Remove Workspace Member","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-21-remove-workspace-member/spec.md","filePath":"feature/agency-workspace/3-4-21-remove-workspace-member/spec.md"}'),i={name:"feature/agency-workspace/3-4-21-remove-workspace-member/spec.md"};function s(n,e,c,l,d,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-4-21-remove-workspace-member" tabindex="-1">3.4.21 Remove Workspace Member <a class="header-anchor" href="#_3-4-21-remove-workspace-member" aria-label="Permalink to &quot;3.4.21 Remove Workspace Member&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.4.21</td></tr><tr><td>Feature</td><td>Remove Workspace Member</td></tr><tr><td>Domain</td><td>Agency &amp; Workspace (FR 3.4)</td></tr><tr><td>Role</td><td>MANAGER</td></tr><tr><td>Version</td><td>2.3 — 2026-09-23 — rewritten to the standard FR format</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when the MANAGER of a Workspace confirms removal of a member from that Workspace.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> The MANAGER of the Workspace, and only that role.</li><li><strong>Purpose:</strong> Lets the MANAGER take a member out of the Workspace while the member stays in the Agency and can still join other Workspaces.</li><li><strong>Interface:</strong> A Remove action per member in the member table at <code>/workspaces/:id/members</code>, followed by a confirmation dialog.</li><li><strong>Data Processing:</strong> The system loads the member, applies the last-MANAGER guard, and marks the membership inactive without touching the member&#39;s Agency membership.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Remove Member Dialog:</p><ul><li>A Remove action per member in the table on <code>/workspaces/:id/members</code>.</li><li>A confirmation dialog naming the member being removed.</li><li>A blocked state with a clear message when the member is the only active MANAGER of the Workspace.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The Workspace identifier; the member identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> The caller&#39;s role in the Workspace; the member record and its role; the count of active MANAGERs in the Workspace.</li><li><strong>Output:</strong> Confirmation that the membership has been deactivated; no other data is returned.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-35:</strong> <code>@RequireRoleAspect</code> re-reads the caller&#39;s role from the DB at request time; <code>SystemRole.ADMIN</code> bypasses the check. Only MANAGER may remove a member; any other caller → 403 <code>FORBIDDEN</code>. This role check runs before any service-level guard.</li><li><strong>BR-28:</strong> Remove member — only MANAGER may remove (enforced by <code>@RequireRole({MANAGER})</code> at the controller); the last remaining active MANAGER cannot be removed/changed away from MANAGER; removal is a soft-delete (<code>isActive=false</code>), not a row deletion. The member&#39;s Agency membership is never modified, so the removed member remains in the Agency and in their other Workspaces. ⚠ BA conflict (needs team decision): <code>Section5_Requirement_Appendix.md</code> BR-28 still says &quot;only OWNER/MANAGER&quot; and &quot;the last remaining OWNER cannot be removed&quot; — stale wording from before OWNER moved to the Agency level; the actual <code>WorkspaceServiceImpl.removeMember</code>/<code>assertNotLastManager</code> guard is MANAGER-only, with no OWNER role at Workspace level.</li><li><strong>BR-30:</strong> A removed member loses access immediately (no token revocation needed) because every scoped query re-checks membership.</li><li><strong>BR-28 (last-MANAGER guard, checked after the lookup, method <code>assertNotLastManager</code> in <code>WorkspaceServiceImpl</code>):</strong> Removing a member whose role is MANAGER is blocked with 409 <code>LAST_MANAGER_CANNOT_BE_REMOVED</code> (<code>ErrorCode.LAST_MANAGER_CANNOT_BE_REMOVED</code>) when that member is the only active MANAGER of the Workspace. The same guard method is shared with FR 3.4.16 Leave Workspace (<code>leaveWorkspace</code>) and FR 3.4.20 Update Workspace Member Role (<code>updateMemberRole</code>, BR-83) — all three call <code>assertNotLastManager</code>.</li><li><strong>BR-29:</strong> Multi-tenancy — the member lookup is scoped to the Workspace; a member that does not exist, is not active, or belongs to another Workspace → 404 <code>NOT_FOUND</code>.</li><li>Code defines both <code>LAST_OWNER_CANNOT_BE_REMOVED</code> (409) and <code>LAST_MANAGER_CANNOT_BE_REMOVED</code> (409) in <code>ErrorCode.java</code>; <code>removeMember</code>&#39;s actual guard throws <code>LAST_MANAGER_CANNOT_BE_REMOVED</code> — <code>LAST_OWNER_CANNOT_BE_REMOVED</code> is not used by this path.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Caller must be the MANAGER of that Workspace; otherwise 403 <code>FORBIDDEN</code> (BR-35). Toast MSG39.</li><li>The member must exist, be active, and belong to that Workspace (BR-29); otherwise 404 <code>NOT_FOUND</code>. Toast MSG38.</li><li>Removing the only active MANAGER of the Workspace (BR-28) → 409 <code>LAST_MANAGER_CANNOT_BE_REMOVED</code>. Toast MSG37.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>MANAGER opens <code>/workspaces/:id/members</code> and chooses Remove for a member.</li><li>MANAGER confirms in the dialog.</li><li>System confirms the caller holds the MANAGER role in that Workspace (BR-35); otherwise the request fails with 403 <code>FORBIDDEN</code>.</li><li>System loads the member and checks that it exists, is active, and belongs to that Workspace (BR-29); otherwise the request fails with 404 <code>NOT_FOUND</code>.</li><li>System applies the last-MANAGER guard (BR-28): members who are not MANAGER pass, and a MANAGER passes only when another active MANAGER exists in the Workspace.</li><li>System marks the membership inactive (BR-28, BR-30); the member disappears from the active member list; toast MSG36.</li><li>The member&#39;s Agency membership is untouched — they remain in the Agency and in any other Workspace they take part in.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>3.a1: Caller is not the MANAGER of that Workspace (BR-35) → 403 <code>FORBIDDEN</code>, toast MSG39. 3.a2: The screen blocks the action; the caller cannot remove members without the MANAGER role.</li><li>4.a1: Member does not exist, is not active, or belongs to another Workspace (BR-29) → 404 <code>NOT_FOUND</code>, toast MSG38. 4.a2: The screen refreshes the member list, since the target row no longer applies.</li><li>5.a1: Removing the only active MANAGER of the Workspace (BR-28) → 409 <code>LAST_MANAGER_CANNOT_BE_REMOVED</code>, toast MSG37. 5.a2: The MANAGER assigns another member as MANAGER first, then retries the removal.</li><li>The removed member still has Tasks in progress in this Workspace → those Tasks are not automatically unassigned; this behaviour is not yet confirmed for the Workspace scope.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The member&#39;s membership in the Workspace is inactive and the Workspace no longer appears in their list.</li><li>The member&#39;s Agency membership is untouched; they remain in the Agency and in their other Workspaces.</li><li>The Workspace still has exactly one active MANAGER.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>None.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../BA/01-organization-structure.html">01-organization-structure.md</a>, <a href="./../../../BA/03-agency-workspace-management.html">03-agency-workspace-management.md</a></p>',27)])])}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
